    endOffset    int
    startLine    int
    endLine      int
}

type group struct {
    key  string
    size int
    occs []occ
}

func main() {
    opts, args := parseFlags()
    if opts.htmlOut && opts.plumbing {
        log.Fatal("you can have either plumbing or HTML output")
    }

    if opts.verbose {
        log.Println("Building suffix tree")
    }

    files := collectFiles(args, opts.fromFiles, opts.vendor)
    fset := token.NewFileSet()
    parsedFiles, nodes := parseAndSerialize(fset, files)

    if opts.verbose {
        log.Println("Searching for clones")
    }

    groups := findGroups(fset, parsedFiles, nodes, opts.threshold)

    switch {
    case opts.htmlOut:
        writeHTML(groups, parsedFiles)
    case opts.plumbing:
        writePlumbing(groups)
    default:
        writeDefault(groups)
    }
}

func parseFlags() (options, []string) {
    var opts options
    opts.threshold = 15

    fs := flag.NewFlagSet("dupl", flag.ExitOnError)
    fs.Usage = func() { fmt.Fprint(fs.Output(), usageText) }
    fs.BoolVar(&opts.fromFiles, "files", false, "")
    fs.BoolVar(&opts.htmlOut, "html", false, "")
    fs.BoolVar(&opts.plumbing, "plumbing", false, "")
    fs.IntVar(&opts.threshold, "t", 15, "")
    fs.IntVar(&opts.threshold, "threshold", 15, "")
    fs.BoolVar(&opts.vendor, "vendor", false, "")
    fs.BoolVar(&opts.verbose, "v", false, "")
    fs.BoolVar(&opts.verbose, "verbose", false, "")
    fs.Parse(os.Args[1:])
    return opts, fs.Args()
}

func collectFiles(args []string, fromStdin bool, includeVendor bool) []string {
    seen := map[string]bool{}
    var files []string
    add := func(path string) {
        if !seen[path] {
            seen[path] = true
            files = append(files, path)
        }
    }

    if fromStdin {
        scanner := bufio.NewScanner(os.Stdin)
        // Keep the scanner simple; the original treats each line literally,
        // including empty lines.
        for scanner.Scan() {
            add(scanner.Text())
        }
        if err := scanner.Err(); err != nil {
            log.Fatal(err)
        }
        return files
    }

    if len(args) == 0 {
        args = []string{"."}
    }

    for _, root := range args {
        info, err := os.Lstat(root)
        if err != nil {
            log.Fatal(err)
        }
        if !info.IsDir() {
            add(root)
            continue
        }
        err = filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
            if err != nil {
                return err
            }
            if info.IsDir() {
                if !includeVendor && hasVendorComponent(path) {
                    return filepath.SkipDir
                }
                return nil
            }
            if strings.HasSuffix(path, ".go") {
                if includeVendor || !hasVendorComponent(path) {
                    add(path)
                }
            }
            return nil
        })
        if err != nil {
            log.Fatal(err)
        }
    }
    return files
}

func hasVendorComponent(path string) bool {
    for _, part := range strings.FieldsFunc(path, func(r rune) bool { return r == '/' || r == '\\' }) {
        if part == "vendor" {
            return true
        }
    }
    return false
}

func parseAndSerialize(fset *token.FileSet, paths []string) ([]fileData, []nodeRec) {
    var files []fileData
    var allNodes []nodeRec

    for _, path := range paths {
        src, err := os.ReadFile(path)
        if err != nil {
            log.Println(err)
            continue
        }
        file, err := parser.ParseFile(fset, path, src, 0)
        if err != nil {
            log.Println(err)
            continue
        }
        tf := fset.File(file.Package)
        fd := fileData{
            path:       path,
            src:        src,
            tokenFile:  tf,
            lineStarts: computeLineStarts(src),
        }
        fileIdx := len(files)
        files = append(files, fd)
        buildNodesForFile(file, fileIdx, &allNodes)
    }

    for i := range allNodes {
        if allNodes[i].size == 0 {
            computeKey(i, allNodes)
        }
    }
    return files, allNodes
}

func computeLineStarts(src []byte) []int {
    starts := []int{0}
    for i, b := range src {
        if b == '\n' {
            starts = append(starts, i+1)
        }
    }
    return starts
}

func buildNodesForFile(file *ast.File, fileIdx int, allNodes *[]nodeRec) {
    skip := map[ast.Node]bool{}
    if file.Name != nil {
        skip[file.Name] = true
    }
    ast.Inspect(file, func(n ast.Node) bool {
        switch x := n.(type) {
        case *ast.FuncType:
            if x.TypeParams != nil {
                skip[x.TypeParams] = true
            }
        case *ast.TypeSpec:
            if x.TypeParams != nil {
                skip[x.TypeParams] = true
            }
        }
        return true
    })

    var stack []int
    ast.Inspect(file, func(n ast.Node) bool {
        if n == nil {
            if len(stack) > 0 {
                stack = stack[:len(stack)-1]
            }
            return true
        }
        if skip[n] {
            return false
        }
        if gd, ok := n.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
            return false
        }

        idx := len(*allNodes)
        rec := nodeRec{
            kind:    reflect.TypeOf(n).String(),
            fileIdx: fileIdx,
            pos:     n.Pos(),
            end:     n.End(),
        }
        *allNodes = append(*allNodes, rec)
        if len(stack) > 0 {
            parent := stack[len(stack)-1]
            (*allNodes)[parent].children = append((*allNodes)[parent].children, idx)
        }
        stack = append(stack, idx)
        return true
    })
}

func computeKey(idx int, nodes []nodeRec) (string, int) {
    if nodes[idx].size != 0 {
        return nodes[idx].key, nodes[idx].size
    }
    parts := []string{nodes[idx].kind}
    size := 1
    for _, child := range nodes[idx].children {
        ck, cs := computeKey(child, nodes)
        if ck != "" {
            parts = append(parts, ck)
            size += cs
        }
    }
    key := strings.Join(parts, "\x00")
    nodes[idx].key = key
    nodes[idx].size = size
    return key, size
}

func findGroups(fset *token.FileSet, files []fileData, nodes []nodeRec, threshold int) []group {
    byKey := make(map[string]*group)
    for i := range nodes {
        n := &nodes[i]
        if n.size < threshold {
            continue
        }
        o, ok := makeOcc(fset, files, *n)
        if !ok {
            continue
        }
        g := byKey[n.key]
        if g == nil {
            g = &group{key: n.key, size: n.size}
            byKey[n.key] = g
        }
        g.occs = append(g.occs, o)
    }

    var candidates []group
    for _, gp := range byKey {
        if len(gp.occs) < 2 {
            continue
        }
        sortOccs(gp.occs)
        candidates = append(candidates, *gp)
    }

    sort.Slice(candidates, func(i, j int) bool {
        if candidates[i].size != candidates[j].size {
            return candidates[i].size > candidates[j].size
        }
        ai, aj := firstForOrder(candidates[i]), firstForOrder(candidates[j])
        if ai.path != aj.path {
            return ai.path < aj.path
        }
        if ai.endOffset != aj.endOffset {
            return ai.endOffset < aj.endOffset
        }
        if ai.startOffset != aj.startOffset {
            return ai.startOffset < aj.startOffset
        }
        return candidates[i].key < candidates[j].key
    })

    var accepted []group
    for _, cand := range candidates {
        if isPruned(cand, accepted) {
            continue
        }
        accepted = append(accepted, cand)
    }

    sort.SliceStable(accepted, func(i, j int) bool {
        ai, aj := firstForOrder(accepted[i]), firstForOrder(accepted[j])
        if ai.path != aj.path {
            return ai.path < aj.path
        }
        if ai.endOffset != aj.endOffset {
            return ai.endOffset < aj.endOffset
        }
        if ai.startOffset != aj.startOffset {
            return ai.startOffset < aj.startOffset
        }
        if accepted[i].size != accepted[j].size {
            return accepted[i].size > accepted[j].size
        }
        return accepted[i].key < accepted[j].key
    })
    return accepted
}

func makeOcc(fset *token.FileSet, files []fileData, n nodeRec) (occ, bool) {
    if n.fileIdx < 0 || n.fileIdx >= len(files) || !n.pos.IsValid() || !n.end.IsValid() {
        return occ{}, false
    }
    sp := fset.Position(n.pos)
    ep := fset.Position(n.end)
    fd := files[n.fileIdx]
    return occ{
        fileIdx:     n.fileIdx,
        path:        fd.path,
        startOffset: sp.Offset,
        endOffset:   ep.Offset,
        startLine:   sp.Line,
        endLine:     ep.Line,
    }, true
}

func sortOccs(occs []occ) {
    sort.SliceStable(occs, func(i, j int) bool {
        if occs[i].path != occs[j].path {
            return occs[i].path < occs[j].path
        }
        if occs[i].startOffset != occs[j].startOffset {
            return occs[i].startOffset < occs[j].startOffset
        }
        if occs[i].endOffset != occs[j].endOffset {
            return occs[i].endOffset < occs[j].endOffset
        }
        return occs[i].startLine < occs[j].startLine
    })
}

func firstForOrder(g group) occ {
    best := g.occs[0]
    for _, o := range g.occs[1:] {
        if o.path < best.path || (o.path == best.path && (o.endOffset < best.endOffset || (o.endOffset == best.endOffset && o.startOffset < best.startOffset))) {
            best = o
        }
    }
    return best
}

func isPruned(cand group, accepted []group) bool {
    for _, big := range accepted {
        if len(big.occs) != len(cand.occs) {
            continue
        }
        used := make([]bool, len(big.occs))
        ok := true
        for _, small := range cand.occs {
            found := false
            for i, b := range big.occs {
                if used[i] {
                    continue
                }
                if containsOcc(b, small) {
                    used[i] = true
                    found = true
                    break
                }
            }
            if !found {
                ok = false
                break
            }
        }
        if ok {
            return true
        }
    }
    return false
}

func containsOcc(big, small occ) bool {
    return big.path == small.path && big.startOffset <= small.startOffset && big.endOffset >= small.endOffset
}

func writeDefault(groups []group) {
    for _, g := range groups {
        fmt.Printf("found %d clones:\n", len(g.occs))
        for _, o := range g.occs {
            fmt.Printf("  %s:%d,%d\n", o.path, o.startLine, o.endLine)
        }
    }
    fmt.Printf("\nFound total %d clone groups.\n", len(groups))
}

func writePlumbing(groups []group) {
    for _, g := range groups {
        if len(g.occs) == 0 {
            continue
        }
        for i, o := range g.occs {
            next := g.occs[(i+1)%len(g.occs)]
            fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", o.path, o.startLine, o.endLine, next.path, next.startLine, next.endLine)
        }
    }
}

func writeHTML(groups []group, files []fileData) {
    fmt.Print(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>
`)
    for i, g := range groups {
        fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(g.occs))
        for _, o := range g.occs {
            fmt.Printf("<h2>%s:%d</h2>\n", o.path, o.startLine)
            fmt.Printf("<pre>%s</pre>\n", html.EscapeString(fragment(files[o.fileIdx], o)))
        }
    }
}

func fragment(fd fileData, o occ) string {
    if len(fd.src) == 0 {
        return ""
    }
    lineIdx := o.startLine - 1
    start := 0
    if lineIdx >= 0 && lineIdx < len(fd.lineStarts) {
        start = fd.lineStarts[lineIdx]
    }
    end := o.endOffset
    if end < start {
        end = start
    }
    if end > len(fd.src) {
        end = len(fd.src)
    }
    // The original renders byte slices; trim a trailing CR only when it is
    // part of a CRLF line ending beyond the syntactic end is unnecessary here.
    return string(bytes.TrimRight(fd.src[start:end], ""))
}
